<template><div class="page-container"><h3>我的考试</h3><el-table :data="papers" v-loading="loading"><el-table-column prop="paperName" label="试卷名称"/><el-table-column prop="duration" label="时长(分钟)"/><el-table-column prop="totalScore" label="总分"/><el-table-column prop="passScore" label="及格分"/><el-table-column label="操作"><template #default="{row}"><el-button type="primary" size="small" @click="$router.push(`/employee/exam/${0}?paperId=${row.paperId || row.id}`)">开始考试</el-button></template></el-table-column></el-table></div></template>
<script setup>import {ref,onMounted} from 'vue';import {getAvailablePapers} from '@/api/exam';const papers=ref([]),loading=ref(false);onMounted(async()=>{loading.value=true;try{papers.value=await getAvailablePapers()}catch(e){}finally{loading.value=false}})</script>
